sys_script_fix.script:
(function(){
	gs.info('inside "Fill in the view_closed_tasks_for_days" fix script');
	if (GlidePluginManager.isActive('com.snc.work_management')){
		var gr = new GlideRecord("central_dispatch_config");
		gr.query();
		while(gr.next()){
			gr.setValue("view_closed_tasks_for_days",7);
			gr.setWorkflow(false);
			gr.update();
		}
	}
})();
